UIAppearance:
export interface UIAppearance {
  theme: 'light' | 'dark';
  reduceMotion: boolean;
}

FeedbackEvent:
export interface FeedbackEvent {
  id: string;
  host?: string;
  content?: ReactNode;
  actions?: ReactNode;
  scope: string;
  context: string;
  revision: string;
  title: string;
  description?: string;
  type: 'error' | 'warning' | 'info' | 'success';
  /** Intent controls configuration actions; automatic presentation defaults to the modal queue. */
  mode: 'modal' | 'notification' | 'manual';
  /** Inbox-only notices do not interrupt the current view. */
  autoOpen?: boolean;
  /**
   * `state` mirrors an ongoing condition and leaves with its source; `event` is a
   * one-off operation result that stays in the inbox until the user clears it.
   */
  kind?: 'state' | 'event';
  actionLabel?: string;
  onAction?: () => void | Promise<unknown>;
  busy?: boolean;
  /** Dialog icon names for the glyph and the action orb; default to the type's icons. */
  icon?: string;
  actionIcon?: string;
}

FeedbackEntry:
export interface FeedbackEntry extends FeedbackEvent {
  lease: number;
  queued: boolean;
  /** When this revision first arrived. */
  at: number;
}

MoonLoaderProps:
export type MoonLoaderProps = Omit<ComponentProps<'span'>, 'children'> & {
  /** small 14px · default 20px · large 32px, or any pixel size. Omit to follow the host (Spin, orb). */
  size?: keyof typeof sizes | number;
  /** Announced as a status; without it the loader is decorative. */
  label?: string;
};

DialogFieldProps:
export type DialogFieldProps = {
  label?: ReactNode;
  /** Muted text at the end of the label row, such as 可选 or a live value. */
  extra?: ReactNode;
  hint?: ReactNode;
  /** Paints the hint red or green, adds its icon and announces it. */
  status?: 'error' | 'ok';
  /** Id for the hint so the control can reference it with aria-describedby. */
  hintId?: string;
  /** Id of the label text, for controls labelled with aria-labelledby. */
  labelId?: string;
  /** Id of the control the label points at. */
  htmlFor?: string;
  /** Monospace input text for paths, refs and keys. */
  mono?: boolean;
  className?: string;
  children?: ReactNode;
};

DialogBadgeProps:
export type DialogBadgeProps = Omit<HTMLAttributes<HTMLSpanElement>, 'children'> & {
  tone?: Tone;
  mono?: boolean;
  icon?: DialogIconName;
  style?: CSSProperties;
  children?: ReactNode;
};

